#!/bin/bash
# =============================================================================
# Behavioral Eval Scorer for cot-reasoning
#
# Scores a directory of flows generated by a model executing the skill against
# the expected profiles in assets/behavioral-eval/prompts.json.
#
# For each prompt id, the flows directory must contain <id>.md — the flow the
# model emitted for that prompt. The scorer:
#   1. runs the contract validator on the flow (pass / fail)
#   2. extracts the actual mode / thinking type / pattern
#   3. checks the expected disciplines are present
#   4. prints a matrix and a summary
#
# Usage: ./scripts/run-behavioral-eval.sh <flows_dir> [label]
#   flows_dir  directory containing <prompt-id>.md files
#   label      free-text label for the results line (model + environment)
#
# Returns:
#   0 - every flow passed the validator and matched its expected profile
#   1 - at least one flow failed validation or deviated from the profile
#   2 - setup error
# =============================================================================

set -uo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
VALIDATOR="${SCRIPT_DIR}/validate-system-flow.sh"
PROMPTS="${SCRIPT_DIR}/../assets/behavioral-eval/prompts.json"

if [[ ! -x "$VALIDATOR" ]]; then
    echo "Validator not found or not executable: $VALIDATOR" >&2
    exit 2
fi
if [[ ! -f "$PROMPTS" ]]; then
    echo "Prompts library not found: $PROMPTS" >&2
    exit 2
fi
if [[ $# -lt 1 || ! -d "$1" ]]; then
    echo "Usage: $0 <flows_dir> [label]" >&2
    exit 2
fi
FLOWS_DIR="$1"
LABEL="${2:-unlabeled}"

field_of() { # $1 = content, $2 = label
    sed -n "s/.*\*\*${2}:\*\* *//p" <<< "$1" | head -1 | awk '{print $1}' | sed 's/ *$//'
}

total=0
validator_pass=0
profile_match=0
rows=""

for id in $(jq -r '.prompts[].id' "$PROMPTS"); do
    total=$((total + 1))
    flow="$FLOWS_DIR/$id.md"
    if [[ ! -f "$flow" ]]; then
        rows+="| $id | MISSING | - | - | - | no |\n"
        continue
    fi

    # 1. Contract validation
    log="$(mktemp)"
    "$VALIDATOR" -s "$flow" > "$log" 2>&1
    vexit=$?
    if [[ $vexit -eq 0 ]]; then
        vpass="pass"
        validator_pass=$((validator_pass + 1))
    else
        vpass="FAIL"
    fi

    content="$(cat "$flow")"
    exp_mode=$(jq -r ".prompts[] | select(.id == \"$id\") | .expected_mode" "$PROMPTS")
    exp_type=$(jq -r ".prompts[] | select(.id == \"$id\") | .expected_thinking_type" "$PROMPTS")
    exp_pattern=$(jq -r ".prompts[] | select(.id == \"$id\") | .expected_pattern" "$PROMPTS")
    exp_disc=$(jq -r ".prompts[] | select(.id == \"$id\") | .expected_disciplines | join(\",\")" "$PROMPTS")

    act_mode=$(field_of "$content" "Reasoning Mode")
    act_type=$(field_of "$content" "Thinking Type")
    act_pattern=$(sed -n "s/.*\*\*Pattern:\*\* *//p" <<< "$content" | head -1 | sed 's/ *$//')

    # 3. Discipline presence
    disc_ok="yes"
    disc_missing=""
    check_disc() { # $1 = extended regex, $2 = discipline name
        if ! grep -qE "$1" <<< "$content"; then
            disc_ok="no"
            disc_missing+="$2 "
        fi
    }
    [[ "$exp_disc" == *formalization* ]] && check_disc "Formaliz" "formalization"
    [[ "$exp_disc" == *verification_loop* ]] && check_disc "Max Iterations" "verification_loop"
    [[ "$exp_disc" == *confidence_gate* ]] && check_disc "Confidence Gate" "confidence_gate"
    [[ "$exp_disc" == *typed_outputs* ]] && check_disc "Output Schema" "typed_outputs"
    [[ "$exp_disc" == *edge_coverage* ]] && check_disc "Edge|coverage|graph" "edge_coverage"

    # 2. Profile match
    prof_ok="yes"
    [[ "$exp_mode" != "any" && "$act_mode" != "$exp_mode" ]] && prof_ok="no"
    [[ "$exp_type" != "any" && "$act_type" != "$exp_type" ]] && prof_ok="no"
    if [[ "$exp_pattern" != "any" && -n "$act_pattern" && "$act_pattern" != "$exp_pattern" ]]; then
        prof_ok="no"
    fi
    [[ "$disc_ok" == "yes" ]] || prof_ok="no"

    if [[ "$prof_ok" == "yes" ]]; then
        profile_match=$((profile_match + 1))
    fi

    rows+="| $id | $vpass | $act_mode (exp $exp_mode) | $act_type (exp $exp_type) | ${disc_missing:-all present} | $prof_ok |\n"
    rm -f "$log"
done

echo ""
echo "## Behavioral eval: $LABEL"
echo ""
echo "| Prompt | Validator | Mode | Thinking type | Missing disciplines | Profile |"
echo "|--------|-----------|------|---------------|---------------------|---------|"
printf "$rows"
echo ""
echo "Summary: validator $validator_pass/$total, profile $profile_match/$total"
echo ""

if [[ "$validator_pass" -eq "$total" && "$profile_match" -eq "$total" ]]; then
    echo "OK: all flows passed and matched their expected profiles"
    exit 0
else
    echo "FAIL: see deviations above"
    exit 1
fi
